<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class GraduateEmploymentController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head')||$r->user()->canDo('students.manage'),403);}
 public function index(Request $r){$this->ok($r);$students=DB::table('students as s')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->leftJoin('specialties as sp','sp.id','=','g.specialty_id')->whereIn('s.status',['active','graduated'])->select('s.id','s.last_name','s.first_name','s.middle_name','s.status','g.name as group_name','sp.name as specialty_name')->orderBy('s.last_name')->get();$records=DB::table('graduate_employment_records as er')->join('students as s','s.id','=','er.student_id')->leftJoin('employers as e','e.id','=','er.employer_id')->select('er.*','s.last_name','s.first_name','e.name as employer_name')->orderByDesc('er.created_at')->get();$employers=DB::table('employers')->where('active',1)->orderBy('name')->get();$vacancies=DB::table('employment_vacancies as v')->join('employers as e','e.id','=','v.employer_id')->where('v.active',1)->select('v.*','e.name as employer_name')->orderBy('v.title')->get();$actual=$records->where('record_type','actual');return view('employment.index',['students'=>$students,'records'=>$records,'employers'=>$employers,'vacancies'=>$vacancies,'actualCount'=>$actual->where('status','employed')->count(),'specialtyCount'=>$actual->where('status','employed')->where('by_specialty',1)->count()]);}
 public function employer(Request $r){$this->ok($r);$d=$r->validate(['name'=>'required|string|max:255','inn'=>'nullable|string|max:20','contact_person'=>'nullable|string|max:255','phone'=>'nullable|string|max:100','email'=>'nullable|email|max:255','address'=>'nullable|string|max:500','practice_partner'=>'nullable|boolean','note'=>'nullable|string|max:5000']);$d['practice_partner']=$r->boolean('practice_partner');DB::table('employers')->insert($d+['active'=>1,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Работодатель добавлен');}
 public function vacancy(Request $r){$this->ok($r);$d=$r->validate(['employer_id'=>'required|exists:employers,id','title'=>'required|string|max:255','requirements'=>'nullable|string|max:5000','salary_from'=>'nullable|numeric|min:0','employment_type'=>'nullable|string|max:50','valid_until'=>'nullable|date']);DB::table('employment_vacancies')->insert($d+['active'=>1,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Вакансия добавлена');}
 public function resume(Request $r,$student){$this->ok($r);$d=$r->validate(['desired_position'=>'nullable|string|max:255','skills'=>'nullable|string|max:10000','experience'=>'nullable|string|max:10000','preferences'=>'nullable|string|max:10000','ready_to_relocate'=>'nullable|boolean','status'=>'required|in:draft,published,archived']);$d['ready_to_relocate']=$r->boolean('ready_to_relocate');DB::table('employment_resumes')->updateOrInsert(['student_id'=>$student],$d+['updated_at'=>now(),'created_at'=>now()]);return back()->with('success','Резюме сохранено');}
 public function record(Request $r){$this->ok($r);$d=$r->validate(['student_id'=>'required|exists:students,id','record_type'=>'required|in:forecast,referral,actual','employer_id'=>'nullable|exists:employers,id','vacancy_id'=>'nullable|exists:employment_vacancies,id','position'=>'nullable|string|max:255','status'=>'required|in:planned,referred,interview,employed,not_employed,continued_education,military_service,parental_leave,unknown','planned_on'=>'nullable|date','employed_on'=>'nullable|date','by_specialty'=>'nullable|boolean','note'=>'nullable|string|max:5000']);$d['by_specialty']=$r->has('by_specialty')?$r->boolean('by_specialty'):null;DB::table('graduate_employment_records')->insert($d+['created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Сведения о трудоустройстве добавлены');}
}